        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine());
        char[] s = in.readLine().trim().toCharArray();
        String[] parts = in.readLine().trim().split("\\s");
        int[] beauty = new int[n];
        int totalBeauty = 0;
        for (int i = 0; i < n; i++) {
            beauty[i] = Integer.parseInt(parts[i]);
            totalBeauty += beauty[i];
        }
        int mismatchCount = 0;
        int[] charFreq = new int[26];
        int sumPairs = 0;
        for (int i = 0; i < n / 2; i++) {
