        for (int i = 0; i < 26; i++) {
            if (charFreq[i] > maxFreq) {
                maxFreq = charFreq[i];
                maxChar = i;
            }
        }
        if (2 * maxFreq <= mismatchCount) {
            System.out.println(totalBeauty);
            return;
