#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<int> beauty(n);
    for (int i = 0; i < n; i++) {
        cin >> beauty[i];
    }
    int totalBeauty = accumulate(beauty.begin(), beauty.end(), 0);
    int mismatchCount = 0;
    vector<int> charFreq(26, 0);
    int sumPairs = 0;
    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - i - 1]) {
            mismatchCount++;
            charFreq[s[i] - 'a']++;
            sumPairs += min(beauty[i], beauty[n - i - 1]);
        }
    }
    int maxFreq = 0;
    int maxChar = 0;
    for (int i = 0; i < 26; i++) {
        if (charFreq[i] > maxFreq) {
            maxFreq = charFreq[i];
            maxChar = i;
        }
    }
    if (2 * maxFreq <= mismatchCount) {
        cout << totalBeauty << "\n";
        return 0;
    }
    vector<int> candidates;
    for (int i = 0; i < n / 2; i++) {
        if ((s[i] - 'a') != maxChar && (s[n - i - 1] - 'a') != maxChar && s[i] != s[n - i - 1]) {
            candidates.push_back(min(beauty[i], beauty[n - i - 1]));
        }
    }
    sort(candidates.begin(), candidates.end());
    int toRemove = 2 * maxFreq - mismatchCount;
    for (int i = 0; i < toRemove; i++) {
        totalBeauty -= candidates[i];
    }
    cout << totalBeauty << "\n";
    return 0;
}

